function getQualysTranslation(key, lang) {
    return (qualysTranslations[lang] && qualysTranslations[lang][key]) ||
           (qualysTranslations.en && qualysTranslations.en[key]) || null;
}

function applyQualysTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.qualys.") || key.startsWith("review.common."))) {
            const translation = getQualysTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} qualys translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applyQualysTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyQualysTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyQualysTranslations(window.i18n?.getCurrentLanguage() || "en");
}
